import itertools

def solve():
    # We want to check if r=2/3 works for various S.
    # P1 = {f-g for f,g in S}
    # P2 = {2*p*q for p,q in P1}
    # P3 = {x*x + y*y - z*z - w*w for x,y,z,w in P1}

    def check(S, r_val):
        P1 = set()
        for f in S:
            for g in S:
                P1.add(f - g)

        P2 = set()
        for p in P1:
            for q in P1:
                P2.add(2 * p * q * r_val * 3 / 2) # 3*p*q*r = 2*p*q*(3r/2). If r=2/3, 3r/2 = 1.
                                                # So P2 = {2*p*q | p,q in P1} is not quite right.
                                                # The problem says P2 = {3pqr | p,q in P1}.
                                                # If r = 2/3, then 3*p*q*r = 3*p*q*(2/3) = 2pq.
                                                # So P2 = {2pq | p,q in P1}.

        # Let's correct P2:
        P2 = set()
        for p in P1:
            for q in P1:
                P2.add(2 * p * q)

        P1_list = list(P1)
        P1_sq = [x*x for x in P1_list]
        P3 = set()
        for i in range(len(P1_sq)):
            for j in range(len(P1_sq)):
                for k in range(len(P1_sq)):
                    for l in range(len(P1_sq)):
                        P3.add(P1_sq[i] + P1_sq[j] - P1_sq[k] - P1_sq[l])

        for val in P2:
            if val not in P3:
                return False, val
        return True, None

    # Test with some S
    for n in range(3, 7):
        S = list(range(n))
        res, bad_val = check(S, 2/3)
        print(f"S={S}, result={res}, bad_val={bad_val}")

solve()

