    for f in S:
        for g in S:
            P1.add(f - g)

    P2 = set()
    for p in P1:
        for q in P1:
            P2.add(3 * p * q * r_val)

    P1_list = list(P1)
    P1_sq = [x*x for x in P1_list]
    P3 = set()
    # P3 is quite large, we might need to be careful.
    # However, for small S, it should be fine.
    for i in range(len(P1_sq)):
        for j in range(len(P1_sq)):
            for k in range(len(P1_sq)):
                for l in range(len(P1_sq)):
                    val = P1_sq[i] + P1_sq[j] - P1_sq[k] - P1_sq[l]
                    P3.add(round(val, 10)) # Round to handle floating point issues

    for val in P2:
        val_rounded = round(val, 10)
        if val_rounded not in P3:
            return False, val
    return True, None

