import random

def check_large(S, r_val):
    P1 = set()
    for f in S:
        for g in S:
            P1.add(f - g)

    P2 = set()
    for p in P1:
        for q in P1:
            P2.add(3 * p * q * r_val)

    P1_list = list(P1)
    P1_sq = [x*x for x in P1_list]

    # Instead of P3, let's just check if each val in P2 can be represented.
    # We need to check if val = x^2 + y^2 - z^2 - w^2.
    # This is val + z^2 + w^2 = x^2 + y^2.

    # Precompute all possible x^2 + y^2
    sums_of_two_sq = set()
    for i in range(len(P1_sq)):
        for j in range(i, len(P1_sq)):
            sums_of_two_sq.add(round(P1_sq[i] + P1_sq[j], 8))

    for val in P2:
        val_rounded = round(val, 8)
        found = False
        for i in range(len(P1_sq)):
            for j in range(i, len(P1_sq)):
                target = val_rounded + P1_sq[i] + P1_sq[j]
                if round(target, 8) in sums_of_two_sq:
                    found = True
                    break
            if found:
                break
        if not found:
            return False, val
    return True, None

